/**
 * The page's single EventService, created without React.
 *
 * ── Why this exists ────────────────────────────────────────────────
 *
 * The dataLayer bridge is started at PAGE level (`init()` in the bundle), but
 * until now the only thing that ever created an EventService was
 * `OmniguideProvider`. So on a page where no provider mounts — cart, checkout,
 * order confirmation — the bridge polled every second, found no sink, and
 * delivered nothing. Silently: no error, no log, and the backlog died with the
 * document. `purchase` fires on exactly such a page, so the order event never
 * left the browser and the de-duplication guard it feeds was never reached.
 *
 * ── Why a shared service rather than a buffer in the bridge ────────
 *
 * A buffer inside the bridge could hold entries across a provider-less page,
 * but holding is not delivering: the page would still have no transport. The
 * thing missing on these pages is an EventService, and EventService ALREADY
 * solves every hard part — a localStorage-backed queue, retry, and a
 * `pagehide`/`visibilitychange` beacon that survives the tab closing. A second
 * buffer would duplicate all of it and still need this to finish the job.
 *
 * ── Why it must be the ONLY one ────────────────────────────────────
 *
 * Every EventService reads and writes the same `omniguide_event_queue` key.
 * Two live instances on one page do not split the work; they fight over it —
 * the second one's constructor loads (and clears) whatever the first persisted,
 * so the same event can be delivered by both. `ensurePageEventService` is
 * therefore idempotent: the first caller creates the service and every later
 * caller, including the provider, is handed that same instance.
 */

import { createScopedLogger } from '../logger.js';
import { getSessionId } from '../session-registry.js';
import { DEFAULT_STORAGE_KEYS } from '../storage.js';
import {
  getConsentService,
  getEventService,
  registerConsentService,
  registerEventService,
} from '../event-registry.js';
import type { OmniguideConsentConfig } from '../types.js';
import { createConsentService, type ConsentService } from './consent.js';
import { createEventService, type EventService } from './events.js';

const log = createScopedLogger('PageEvents');

export interface PageEventServiceConfig {
  /** Fully resolved backend base URL. No service is created without one. */
  apiBaseUrl: string;
  /** Website identifier, sent as `website_code`. */
  websiteId: string;
  /** Consent reader configuration, as the provider passes it. */
  consent?: OmniguideConsentConfig;
  /** Where this storefront persists its session id. */
  sessionStorageKey?: string;
}

/**
 * The session this shopper already has, or undefined.
 *
 * EventService refuses to flush or beacon without a session id, and on a page
 * that mounts no widget nothing ever populates the in-memory session registry
 * — so storage is the only place a session can be found. Deliberately only
 * READS: minting a session here would open one for every shopper on every
 * cart and checkout page, which is a backend cost the storefront never asked
 * for. With no session the events stay queued (24h) and go out on the next
 * page that has one.
 */
function existingSessionId(websiteId: string, storageKey?: string): string | undefined {
  const fromRegistry = getSessionId(websiteId);
  if (fromRegistry) return fromRegistry;
  try {
    const key = storageKey ?? DEFAULT_STORAGE_KEYS.sessionId;
    return localStorage.getItem(key) ?? undefined;
  } catch {
    return undefined;
  }
}

/**
 * What the one live service was built with, for the mismatch warning below.
 */
let createdWith: { apiBaseUrl: string; websiteId: string } | null = null;

/**
 * Warn when a later caller wanted a DIFFERENT backend than the live service.
 *
 * The first caller wins, silently, which is right for the queue but wrong to
 * hide: a console `setPreviewApi` followed by a lazily-mounted widget leaves
 * feedback pointing at staging while events still go to production. Nothing
 * else on the page would ever say so.
 */
function warnOnConfigMismatch(config: PageEventServiceConfig): void {
  if (!createdWith) return;
  if (createdWith.apiBaseUrl === config.apiBaseUrl && createdWith.websiteId === config.websiteId) return;
  log.warn(
    `Keeping the page's EventService (${createdWith.websiteId} @ ${createdWith.apiBaseUrl}); ` +
    `ignoring a later request for ${config.websiteId} @ ${config.apiBaseUrl}. Reload to change it.`,
  );
}

function buildConsentService(config: PageEventServiceConfig): ConsentService {
  return createConsentService({
    apiBaseUrl: config.apiBaseUrl,
    reader: config.consent?.reader,
    cookieName: config.consent?.cookieName,
    magentoCookieName: config.consent?.magentoCookieName,
    magentoWebsiteId: config.consent?.magentoWebsiteId,
  });
}

/**
 * Get the page's EventService, creating and registering it if there is none.
 *
 * Safe to call from anywhere, as often as you like — see the file header for
 * why exactly one instance per page is not an optimisation but a correctness
 * requirement.
 */
export function ensurePageEventService(config: PageEventServiceConfig): EventService | null {
  // Server-side there is no page to be the single sink FOR, and EventService
  // would start a flush interval nothing ever clears — while handing every
  // later request the first one's websiteId.
  if (typeof window === 'undefined') return null;

  const existing = getEventService();
  if (existing) {
    warnOnConfigMismatch(config);
    return existing;
  }
  if (!config.apiBaseUrl) {
    // Loud, because this is the failure the ticket was about: a bridge running
    // against no sink looks identical to a page with nothing to forward.
    log.warn('No apiBaseUrl: events cannot be delivered from this page.');
    return null;
  }

  const consentService = getConsentService() ?? buildConsentService(config);
  registerConsentService(consentService);

  const eventService = createEventService({
    apiBaseUrl: config.apiBaseUrl,
    consentService,
    websiteId: config.websiteId,
  });
  // Seeded before registration so the first event handed over by a waiting
  // bridge can be flushed immediately rather than waiting a tick for context.
  eventService.updateContext({
    sessionId: existingSessionId(config.websiteId, config.sessionStorageKey),
  });
  registerEventService(eventService);
  createdWith = { apiBaseUrl: config.apiBaseUrl, websiteId: config.websiteId };
  log.debug('Page-level EventService created');
  return eventService;
}
