/**
 * Typeahead — federated fast-path search shown beneath the search input as
 * the user types. One round-trip returns four sections: products, categories,
 * content, brands. A top-level `is_question` flag tells the UI the backend
 * detected a natural-language question and deliberately suppressed fuzzy
 * matches (all sections empty) — render a "press Search to ask" hint instead.
 *
 * Contract source of truth:
 *   verdict-SOI-708-fast-search-path/docs/typeahead-frontend-spec.md
 *
 * Fields stay in snake_case to mirror the backend payload verbatim — the spec
 * is authoritative and other frontends consume the identical shape. Do NOT add
 * fields the backend doesn't return; the trimmed shape is deliberate.
 */

export interface TypeaheadHighlight {
  /** Which field matched: "title" | "name" | "brand" | "sku" | … */
  field: string;
  /** Query tokens that matched this field. */
  matched_tokens: string[];
  /** Server-rendered, server-sanitized HTML with <mark> around matches. */
  snippet?: string;
}

export interface ProductHit {
  /** Stable doc id — safe to use as a React key. */
  id: string;
  /** Display SKU as authored (case + separators preserved). */
  sku: string;
  /** Display title; pre-resolved across variants/parent — show as-is. */
  title: string;
  brand?: string;
  url?: string;
  image_url?: string;
  price?: number;
  highlights: TypeaheadHighlight[];
}

export interface CategoryHit {
  id: string;
  name: string;
  url?: string;
  parent_id?: string;
  /** Total products in this category — drives the "(N items)" caption. */
  product_count: number;
  highlights: TypeaheadHighlight[];
}

export interface ContentHit {
  id: string;
  title: string;
  url?: string;
  /** First ~1500 chars of the body. Truncate at ~140 in the row. */
  snippet?: string;
  /** "document" | "article" | "faq" | "help" — drives the row icon. */
  content_type?: string;
  highlights: TypeaheadHighlight[];
}

export interface BrandHit {
  id: string;
  name: string;
  url?: string;
  /** Total products under this brand. */
  product_count: number;
  highlights: TypeaheadHighlight[];
}

export interface TypeaheadSectionPayload<H> {
  /** Total matches — NOT the page size. Use for "view all N" affordances. */
  found: number;
  /** The page actually returned. */
  hits: H[];
}

export interface TypeaheadSections {
  products: TypeaheadSectionPayload<ProductHit>;
  categories: TypeaheadSectionPayload<CategoryHit>;
  content: TypeaheadSectionPayload<ContentHit>;
  brands: TypeaheadSectionPayload<BrandHit>;
}

/**
 * Section keys in spec render order (products → categories → content →
 * brands). Centralized here so the dropdown and keyboard navigation iterate
 * in one consistent order.
 */
export const TYPEAHEAD_SECTION_ORDER = [
  'products',
  'categories',
  'content',
  'brands',
] as const;
export type TypeaheadSectionKey = (typeof TYPEAHEAD_SECTION_ORDER)[number];

export interface TypeaheadRequest {
  /** Tenant — storefront URL or namespace string. */
  website_code: string;
  /** Raw user input; backend normalizes, do not transform client-side. */
  query: string;
  /** Per-section page size override. Default products=8, others=4. Cap 20. */
  per_page?: number;
  /** When true, includes out-of-stock products. Default false. */
  allow_oos?: boolean;
}

export interface TypeaheadResponse {
  query: string;
  /**
   * When true the backend detected a natural-language question and suppressed
   * fuzzy matches; every section is empty. Render the "press Search to ask"
   * hint, never the section panels.
   */
  is_question: boolean;
  /** End-to-end backend ms (0 when is_question short-circuits). */
  latency_ms: number;
  backend: 'typesense';
  sections: TypeaheadSections;
}

/**
 * Discriminated outcome from {@link fetchTypeaheadSearch}, splitting the four
 * cases that drive distinct UI states:
 *  - ok       → render sections (or the question hint when data.is_question)
 *  - disabled → 503 (Typesense off/unhealthy); hide the surface for the session
 *  - aborted  → a newer keystroke superseded this request; do nothing
 *  - error    → transient failure for this keystroke; collapse the dropdown only
 */
export type TypeaheadResult =
  | { kind: 'ok'; data: TypeaheadResponse }
  | { kind: 'disabled' }
  | { kind: 'aborted' }
  | { kind: 'error'; status?: number };

/** Union of all hit types, for code that dispatches by section generically. */
export type TypeaheadAnyHit = ProductHit | CategoryHit | ContentHit | BrandHit;
