/**
 * Recommendation bus (SOI-813).
 *
 * A tiny typed emit/subscribe helper over a `window` CustomEvent. It bridges
 * recommendation match data out of the React layer to pure-DOM host decorators
 * (PLP grid match ribbons, PDP image match badge) without coupling them to
 * React. SSR-safe — every entry point no-ops when `window` is undefined.
 */

/** Event name carried on `window` for recommendation match data. */
export const RECOMMENDATIONS_EVENT = 'omniguide:recommendations';

/** Which surface the recommendations were resolved for. */
export type RecommendationPage = 'plp' | 'pdp';

/** A single product's match data, keyed for host-DOM lookup by SKU. */
export interface RecommendationMatch {
  sku: string;
  matchPct?: number;
  rank?: number;
  // Optional display data. Host-DOM decorators (ribbons) only need `sku`, but
  // consumers that RENDER the recommendations — e.g. the PLP "filtered subset"
  // mode — use these to show the products without a separate fetch. Present
  // when the producer already has hydrated products (search / category guide).
  id?: string | number;
  name?: string;
  brand?: string;
  url?: string;
  image_url?: string;
  price?: number | string;
  retail_price?: number | string;
}

/** Payload carried by the `omniguide:recommendations` CustomEvent. */
export interface RecommendationsPayload {
  page: RecommendationPage;
  products: RecommendationMatch[];
  /**
   * What produced these (e.g. 'search', 'category_guide'). Lets a consumer
   * decide whether to act — the PLP filtered mode reacts to producers that
   * carry display data so it can render the subset.
   */
  source?: string;
}

/**
 * Emit a recommendations payload on `window`. No-op during SSR.
 * Subscribers added after emit can read the last payload via {@link getLastRecommendations}.
 */
export function emitRecommendations(payload: RecommendationsPayload): void {
  if (typeof window === 'undefined') return;
  (window as unknown as Record<string, unknown>)[LAST_KEY] = payload;
  window.dispatchEvent(new CustomEvent<RecommendationsPayload>(RECOMMENDATIONS_EVENT, { detail: payload }));
}

const LAST_KEY = '__omniguideLastRecommendations';

/**
 * Read the most recently emitted payload (if any) — lets a decorator that
 * mounts after recommendations resolved still pick up the data. SSR-safe.
 */
export function getLastRecommendations(): RecommendationsPayload | null {
  if (typeof window === 'undefined') return null;
  return ((window as unknown as Record<string, unknown>)[LAST_KEY] as RecommendationsPayload | undefined) ?? null;
}

/**
 * Subscribe to recommendation payloads. Returns an unsubscribe function.
 * SSR-safe — returns a no-op unsubscribe when `window` is undefined.
 */
export function onRecommendations(handler: (payload: RecommendationsPayload) => void): () => void {
  if (typeof window === 'undefined') return () => {};
  const listener = (e: Event): void => {
    const detail = (e as CustomEvent<RecommendationsPayload>).detail;
    if (detail) handler(detail);
  };
  window.addEventListener(RECOMMENDATIONS_EVENT, listener);
  return () => window.removeEventListener(RECOMMENDATIONS_EVENT, listener);
}
