/**
 * DataLayer bridge — forwards a storefront's own analytics arrays into
 * EventService.
 *
 * "The dataLayer" is not one array, and assuming it is loses every eCommerce
 * event on some stores:
 *
 * - `window.dataLayer` is GTM's transport. It carries `gtm.js` / `gtm.dom` /
 *   `gtm.load` plus whatever tags push, so `gtm.`-prefixed names are filtered
 *   out and anything else is forwarded.
 * - `window.ElevarDataLayer` is Elevar's own array. Elevar owns its event
 *   schema and enriches before GTM sees anything, so on an Elevar store every
 *   eCommerce signal (`dl_view_item`, `dl_add_to_cart`, `dl_begin_checkout`,
 *   `dl_purchase`, …) lands HERE and never in `window.dataLayer`. Measured on
 *   a production Elevar storefront across a PLP and a PDP: the GTM array held
 *   nothing but lifecycle events, while the Elevar array held the full payload.
 *
 * Event names are forwarded VERBATIM. The backend owns spelling
 * (`event_name_normalizer.canonical_event_name`), so a new storefront
 * vocabulary is a config row there rather than a mapping table here that can
 * drift out of sync with it.
 *
 * `foldEventName` folds case and separators, and does NOT weaken that rule: it
 * builds a de-duplication KEY and is used nowhere else. Nothing it produces is
 * ever handed to EventService, so it decides only whether two entries are the
 * same occurrence — never what an event is called on the wire. Keeping it
 * shape-based is what keeps it maintenance-free: there is no alias list here
 * to fall behind the backend's.
 *
 * ONE event is interpreted rather than only relayed: `purchase`. It is the only
 * canonical event whose backend handler parses the payload, so a duplicate
 * corrupts an order record instead of costing a redundant row. See
 * `PURCHASE_EVENTS` for why that is a guard list and not a spelling map.
 *
 * Both arrays are read by polling, never by wrapping `push` — Elevar replaces
 * `push` with its own implementation, so patching it fights the vendor for
 * ownership of a function we do not own. Each poll forwards the entries it has
 * not already forwarded, tracked by object identity rather than by a count
 * (see `forwarded`), and then screens what is left by CONTENT so that one
 * action tagged under two spellings is not counted twice (see the
 * dual-spelling guard).
 *
 * ── Why the progress state is module-level ──────────────────────────
 *
 * The bridge is started at PAGE level (`init()` in the bundle), not from a
 * mounted provider — that was the SOI-2291 fix, because a cart or checkout
 * page mounts no widget at all. But `init()` can be called more than once on a
 * page, and the bridge is still exported for a consumer to start directly.
 *
 * So `forwarded`, `pageViewSent`, `countedPurchases` and `recentEvents` CANNOT
 * live in a start call's closure: a stop→start cycle would forget them and
 * re-forward the entire array, a second `page_view`, an order already counted,
 * and the spelling of an event just sent. They live
 * at module scope, where a detach cannot reach them, and the poller itself is
 * refcounted so the last detach — not the first — stops it.
 */

import { createScopedLogger } from '../logger.js';
import { sanitizeUrl } from '../safe-url.js';
import { getEventService, onEventServiceRegistered } from '../event-registry.js';

const log = createScopedLogger('DataLayerBridge');

const POLL_INTERVAL_MS = 1000;

export interface DataLayerBridgeConfig {
  /** Watch `window.ElevarDataLayer`. */
  elevar?: boolean;
  /** Watch `window.dataLayer`, skipping GTM's own lifecycle events. */
  gtm?: boolean;
  /** Emit exactly one `page_view` per document load. */
  pageView?: boolean;
}

interface SourceSpec {
  /** Global holding the array. */
  key: string;
  /** Names this source must not forward. */
  skip?: (eventName: string) => boolean;
}

const SOURCES: Record<'elevar' | 'gtm', SourceSpec> = {
  elevar: { key: 'ElevarDataLayer' },
  // The filter is the GTM source's, not the bridge's: an Elevar store that
  // ever names an event `gtm.something` must still be forwarded.
  gtm: { key: 'dataLayer', skip: name => name.startsWith('gtm.') },
};

/**
 * Which entries have already been handed to EventService.
 *
 * Progress is tracked by entry IDENTITY, not by a count. A length index is the
 * wrong signal for an array we do not own: a vendor can clear it in place and
 * refill it to the same length (an index forwards the refill's first entries
 * and loses the rest, permanently), swap in a copy (an index re-forwards
 * everything, double-counting a `dl_purchase`), push a superset copy, or
 * `splice` out an entry (shifting every later one under the index). No pair of
 * length/array-identity guards handles all of those — the equal-length and
 * superset cases pull in opposite directions.
 *
 * Forwarding each OBJECT once collapses all of them into one rule, and needs
 * no reconciliation: a refilled array holds new objects, so they are forwarded;
 * a copied or spliced array holds the same objects, so they are not.
 *
 * ponytail: rescans the whole array each tick rather than remembering a
 * position. These arrays hold tens of entries, not thousands. If one ever grows
 * past a few hundred, keep a hint index for the common append-only case and
 * fall back to the full scan when identity says the array changed.
 *
 * A WeakSet, so a cleared array's entries are collectable — this outlives every
 * detach and must not pin a page's worth of vendor payloads.
 */
let forwarded = new WeakSet<object>();

/**
 * Most entries forwarded in one tick.
 *
 * The bridge holds everything until an EventService registers and then replays
 * it in one synchronous pass. EventService's queue trims OLDEST-first at 200,
 * so an unpaced replay of a large backlog evicts the very entries the hold
 * existed to preserve, plus any genuine SDK events already queued. Realistic
 * backlogs are 5-30, so this is tail cover; the remainder simply goes next tick.
 */
const MAX_FORWARDS_PER_TICK = 50;

/**
 * Most elements walked in one vendor array.
 *
 * A cap, not a size estimate: `length` is vendor-controlled, and an array
 * Proxy can report a number far larger than anything it holds. Real
 * `ecommerce.items` arrays are single or low double digits, so this is pure
 * tail cover — the bound that keeps a hostile length from being a page freeze.
 * Exceeding it truncates and marks the entry lossy rather than refusing it.
 */
const MAX_ARRAY_ITEMS = 1000;

// ── Module-level progress. A detach must never reset these. ────────
// `countedPurchases` and `recentEvents` belong to this group and are declared
// beside the guards they serve, since each is meaningless without the screening
// that reads it.
let pageViewSent = false;

// ── Module-level poller, refcounted across providers. ──────────────
let refCount = 0;
let intervalId: number | null = null;
let stopLifecycleListeners: (() => void) | null = null;
let activeConfig: DataLayerBridgeConfig | null = null;

/**
 * Consecutive ticks with no EventService before the bridge stops polling.
 *
 * A page can start the bridge and never produce a sink — nothing mounts, and
 * no page-level EventService was configured. Polling a document for its whole
 * life to forward nothing is pure waste, so the bridge stands down.
 *
 * Generous on purpose, because standing down early is the expensive mistake: a
 * provider behind a lazy chunk or a slow network can take many seconds to
 * mount. It is only SAFE to stand down at all because registration wakes the
 * bridge back up (see `standDown`), so the deadline costs nothing if it is
 * wrong — the backlog is still held and still replayed.
 *
 * Note that the bundle creates the page's EventService immediately before
 * starting the bridge, so on a page the SDK itself set up this deadline is
 * never reached. It covers a consumer calling `startDataLayerBridge` directly.
 * Do not "simplify" it away on the grounds that the shipped path cannot hit it.
 */
const MAX_IDLE_TICKS = 60;
let idleTicks = 0;
let awaitingRegistration: (() => void) | null = null;

interface ParsedEntry {
  name: string;
  payload: Record<string, unknown>;
  /**
   * Some part of this entry could not be read, so `payload` is a SUBSET of what
   * the vendor pushed.
   *
   * It exists because failing open on a read is not free: the de-duplication
   * key is built from the payload, so a dropped field can make two genuinely
   * different actions look identical — `add_to_cart` and `addToCart` with the
   * same readable fields and an unreadable `product` would key the same, and
   * the second would be discarded as a spelling of the first. Trading one
   * unreadable event for a wrongly-dropped readable one is a worse bargain
   * than the bug this guard was added to fix.
   *
   * A lossy entry is therefore forwarded but never keyed — see `screenEntry`.
   */
  lossy: boolean;
}

/** Collects whether any read failed while walking one entry. */
interface ReadReport {
  lossy: boolean;
}

/**
 * Parse one array entry into a name and payload, or null if it is not an event.
 *
 * Two shapes reach these arrays, and they must be read as a unit — deciding
 * the name from one shape and the payload from the other mixes them:
 *
 * - a plain object carrying `event` (GTM's convention, and Elevar's);
 * - the `arguments` object gtag pushes for `gtag('event', '<name>', {...})`,
 *   which is array-LIKE but not an Array and carries its parts under
 *   "0" / "1" / "2". gtag's non-event commands (`set`, `config`, `consent`,
 *   `js`) land in the same array and are skipped.
 */
/**
 * Keys EventService puts on the envelope itself.
 *
 * `track()` builds `{ event, timestamp, ...data }` — the caller's data spreads
 * LAST, so any of these surviving in a vendor payload silently overwrites the
 * envelope. A gtag params object carrying `event` renames the event on the
 * wire (`add_to_cart` arriving as whatever the vendor wrote); a `timestamp`
 * replaces the SDK's ISO time with a value of unknown format; a `message_id`
 * attributes a storefront event to an Omniguide conversation that never
 * produced it.
 *
 * `conversation_id` is here for exactly the reason `message_id` is, and the
 * omission was an inconsistency rather than a decision. A third-party chat
 * vendor pushing its own `conversation_id` into the dataLayer would otherwise
 * have that id stored as the Omniguide conversation this event belongs to.
 * Harmless while the backend ignored the field; SOI-2373 makes the backend
 * prefer a per-event `conversation_id`, which turns the same push into a
 * foreign id written to a column attribution reads.
 *
 * Dropped rather than renamed: preserving them under a namespaced key would be
 * inventing vocabulary the backend does not know. If any of this turns out to
 * be worth keeping, it should be a deliberate field, not a collision.
 */
const ENVELOPE_KEYS = ['event', 'timestamp', 'message_id', 'conversation_id'] as const;

/**
 * Marker the SDK stamps on every event it hands its own analytics adapter.
 *
 * `useAnalyticsTracking` delivers each SDK event TWICE by design: once to
 * EventService (backend) and once to the theme's `analyticsAdapter`, whose
 * documented implementation pushes to `window.dataLayer`. With `gtm: true`
 * this bridge reads that array, so without a skip the SDK's own events return
 * through the front door and are counted a second time.
 *
 * A marker rather than a name list: the theme interceptor this replaces
 * skipped by prefix (`ai_search_*`, `AI Search -`, `scroll_for_more`) and that
 * list has already drifted past `rec_product_clicked`, `product_rec_*` and
 * `category_rec_*`. A key travels with the event and cannot fall behind the
 * vocabulary.
 *
 * Limit: it only works for an adapter that spreads the properties it is given
 * onto the pushed object, as the documented one does. An adapter that rebuilds
 * the payload drops the marker and its events round-trip again.
 */
export const SDK_ORIGIN_MARKER = 'omniguide_sdk';

/**
 * Events and payload keys carrying shopper identity, dropped before anything
 * reaches EventService.
 *
 * `track()` persists to `localStorage['omniguide_event_queue']` for 24h BEFORE
 * consent is read, so anything forwarded here is at rest on the shopper's
 * device regardless of what they later deny. `ARCHITECTURE.md` and
 * `SECURITY.md` both publish that no personal information is cached client
 * side, and forwarding Elevar's `dl_user_data` verbatim would make that false.
 *
 * A blocklist, not an allowlist: the whole point of the bridge is that the
 * backend owns the vocabulary, so an allowlist would silently drop each new
 * eCommerce field until someone noticed. This list can only ever err toward
 * forwarding too little of what we already know is identity.
 */
const BLOCKED_EVENTS = new Set(['dl_user_data']);
// `user_data` is the GA4 / Google Ads enhanced-conversions envelope — the
// standard identity carrier in `window.dataLayer`, which is exactly what the
// `gtm` source reads. It holds `email_address`, `phone_number` and an
// `address` block. It was missing here, so the source most likely to carry
// identity was the one source not covered.
const BLOCKED_KEYS = ['user_properties', 'customer', 'user_data'] as const;

// SDK_ORIGIN_MARKER joins these: an entry that reaches the backend carrying it
// would be shipping an internal routing flag as a storefront field.
const DROPPED_KEYS: readonly string[] = [...ENVELOPE_KEYS, ...BLOCKED_KEYS, SDK_ORIGIN_MARKER];

/**
 * Remove the dropped keys at EVERY depth, not just the top level.
 *
 * A one-level strip was the whole protection, and a vendor only has to nest to
 * defeat it: `ecommerce.customer.email` and an `actionField` carrying
 * `user_properties` both reached the queue verbatim while the top-level keys
 * of the same names were being removed. Identity does not reliably sit at the
 * root of these payloads — Elevar's checkout events in particular carry it
 * under `ecommerce`.
 *
 * Rebuilds containers rather than mutating, because this runs on the vendor's
 * live object.
 *
 * `ancestors` tracks the path currently being walked, not every object seen. A
 * WeakSet of everything visited looks like the same thing and is not: a payload
 * that legitimately references one object twice (the same product under two
 * keys) would have the second reference dropped as though it were a cycle.
 * Entries are removed on the way back out, so only a true self-reference —
 * which would otherwise hang the poll on the vendor's own array — resolves to
 * `undefined`.
 *
 * Class instances ARE walked. Passing them through because they are not plain
 * objects fails open: identity inside one would reach the wire untouched, and
 * these payloads are bound for `JSON.stringify` anyway, so rebuilding them as
 * plain objects costs nothing downstream. Only the built-ins whose meaning
 * lives outside their enumerable properties are passed through — a Date
 * rebuilt as `{}` would lose the date.
 */
function stripDroppedKeys(
  payload: Record<string, unknown>,
  report: ReadReport,
  ancestors: Set<object> = new Set(),
): Record<string, unknown> {
  return stripValue(payload, ancestors, report) as Record<string, unknown>;
}

const OPAQUE = [Date, RegExp, Map, Set, WeakMap, WeakSet] as const;

function stripValue(value: unknown, ancestors: Set<object>, report: ReadReport): unknown {
  if (!value || typeof value !== 'object') return value;
  if (OPAQUE.some(ctor => value instanceof ctor)) return value;
  if (ancestors.has(value)) return undefined;

  ancestors.add(value);
  try {
    // Indexed rather than `.map`: an exotic array (a Proxy, or an index defined
    // as a throwing getter) would take the whole array — and with it the whole
    // event — out on one bad element.
    if (Array.isArray(value)) {
      const items: unknown[] = [];
      // Length is read ONCE, before iterating, and never again. `length` is
      // vendor-controlled: a Proxy can return a larger number on every read, so
      // re-reading it per iteration is a loop that never ends — the page
      // freezes and every entry behind this one is blocked. `.map` snapshots
      // the length for exactly this reason, so an indexed loop has to do it
      // explicitly or it is strictly worse than what it replaced. A dropped
      // event is recoverable; a hung storefront is not.
      // Caching `value.length` snapshots the REFERENCE, not a number. A Proxy
      // can hand back an object whose `valueOf()` returns a larger number every
      // time it is coerced, and `i < length` coerces on every comparison — a
      // snapshot in name only, and still a loop that never ends. `Number(...)`
      // forces one conversion, once.
      //
      // The result is validated rather than trusted. `Infinity` bounds nothing
      // and NaN compares false against everything; native `.map` rejects both
      // outright with a RangeError, so a hand-rolled loop that accepts them is
      // worse than the code it replaced.
      let length = 0;
      try {
        const raw = Number(value.length);
        if (!Number.isFinite(raw) || raw < 0) {
          throw new RangeError(`unusable array length: ${String(value.length)}`);
        }
        const wanted = Math.floor(raw);
        length = Math.min(wanted, MAX_ARRAY_ITEMS);
        if (length < wanted) {
          report.lossy = true;
          log.warn(`dataLayer entry: array reports ${wanted} items; walking the first ${MAX_ARRAY_ITEMS}.`);
        }
      } catch (error) {
        report.lossy = true;
        log.warn('dataLayer entry: array length could not be read; forwarding without it:', error);
        return items;
      }
      for (let i = 0; i < length; i++) {
        try {
          items.push(stripValue(value[i], ancestors, report));
        } catch (error) {
          report.lossy = true;
          log.warn(`dataLayer entry: index ${i} could not be read; forwarding without it:`, error);
          items.push(undefined);
        }
      }
      return items;
    }

    const out: Record<string, unknown> = {};
    // `Object.keys` lists own enumerable names WITHOUT invoking a getter;
    // `Object.entries` reads every value, so one throwing getter took the whole
    // entry down — and because `drainSource` marks an entry forwarded before
    // parsing it, that entry was never retried. Reading key by key keeps the
    // blast radius at the poisoned key, which is the fail-OPEN direction AC5
    // asks for: forward what could be read, warn about what could not.
    //
    // `Object.keys` is itself guarded: a Proxy whose `ownKeys` trap throws
    // would otherwise escape the per-key guards below and drop the event, which
    // is the very failure this function was changed to stop. An event with no
    // readable payload still beats no event.
    let keys: string[];
    try {
      keys = Object.keys(value as Record<string, unknown>);
    } catch (error) {
      report.lossy = true;
      log.warn('dataLayer entry: its keys could not be listed; forwarding with an empty payload:', error);
      return out;
    }
    for (const key of keys) {
      if (DROPPED_KEYS.includes(key)) continue;
      // The recursive call is INSIDE the guard, not after it: the read is not
      // the only thing that can throw. An exotic nested value can raise from
      // `instanceof` or from its own key listing, and that would escape a guard
      // wrapped around the read alone — dropping the event for a fault one
      // level down, which is the case this whole change exists to stop.
      try {
        out[key] = stripValue((value as Record<string, unknown>)[key], ancestors, report);
      } catch (error) {
        report.lossy = true;
        log.warn(`dataLayer entry: key "${key}" could not be read; forwarding without it:`, error);
      }
    }
    return out;
  } finally {
    ancestors.delete(value);
  }
}

/**
 * Read one property, treating a throwing getter as absent.
 *
 * Used for the reads `parseEntry` makes BEFORE the payload strip. A vendor
 * object can define `event` or the origin marker as a getter that throws; left
 * unguarded that escapes `parseEntry` entirely and the entry is dropped for
 * good, because it is already in `forwarded`.
 */
function safeRead(source: Record<string, unknown>, key: string, report: ReadReport): unknown {
  try {
    return source[key];
  } catch (error) {
    report.lossy = true;
    log.warn(`dataLayer entry: key "${key}" could not be read:`, error);
    return undefined;
  }
}

/**
 * Walk a payload, treating a failure of the walk ITSELF as an empty payload.
 *
 * The per-key guards inside `stripValue` only start once the walk is under way.
 * The very first thing it does is an `instanceof` sweep, and a Proxy with a
 * throwing `getPrototypeOf` trap raises there — above every guard, straight
 * into `drainSource`, which has already marked the entry forwarded. Guarding
 * the root call keeps the worst case at "an event with no payload" instead of
 * "no event".
 */
function safeStrip(source: Record<string, unknown>, report: ReadReport): Record<string, unknown> {
  try {
    return stripDroppedKeys(source, report);
  } catch (error) {
    report.lossy = true;
    log.warn('dataLayer entry: its payload could not be walked; forwarding with an empty payload:', error);
    return {};
  }
}

function parseEntry(entry: unknown): ParsedEntry | null {
  if (!entry || typeof entry !== 'object') return null;
  const e = entry as Record<string, unknown>;
  // One report per entry, shared by every read below: a failure anywhere —
  // the marker, the name, a nested payload key, an array index — makes the
  // whole entry unkeyable, because any of them could have been the field that
  // told this occurrence apart from the next one.
  const report: ReadReport = { lossy: false };

  // Each branch takes BOTH name and payload from the shape it matched —
  // reading the name off one and the payload off the other would mix them on
  // a hybrid entry. An empty `event` names nothing, so it falls through to the
  // gtag check rather than claiming the entry.
  // Both rejections sit here rather than in the drain loop so they apply to
  // every source and every entry shape, and so a blocked entry is still MARKED
  // as seen — a skipped entry must not be reconsidered on the next tick.
  //
  // A THROWING marker getter reads as absent, which forwards the entry. That is
  // the right way round: the SDK builds its own entries, so they never carry a
  // throwing getter — a throw here means the entry is a vendor's, and vendor
  // entries are exactly what the bridge exists to forward. Treating the throw
  // as "marker present" would drop a storefront event to avoid a round-trip
  // that cannot happen.
  if (safeRead(e, SDK_ORIGIN_MARKER, report)) return null;

  const named = safeRead(e, 'event', report);
  if (typeof named === 'string' && named) {
    if (BLOCKED_EVENTS.has(named)) return null;
    return { name: named, payload: safeStrip(e, report), lossy: report.lossy };
  }

  const gtagVerb = safeRead(e, '0', report);
  const gtagName = safeRead(e, '1', report);
  if (gtagVerb === 'event' && typeof gtagName === 'string' && gtagName) {
    if (BLOCKED_EVENTS.has(gtagName)) return null;
    const params = safeRead(e, '2', report);
    // The marker check above only sees the ENTRY. An adapter written as
    // `gtag('event', name, {...properties})` spreads the properties it is
    // given — which the documented limit says is the safe shape — but they
    // land under `2`, so the marker rides there and the entry itself is bare.
    // Without this the SDK's own events round-trip on that adapter.
    if (params && typeof params === 'object'
        && safeRead(params as Record<string, unknown>, SDK_ORIGIN_MARKER, report)) return null;
    const payload = params && typeof params === 'object'
      ? safeStrip(params as Record<string, unknown>, report)
      : {};
    return { name: gtagName, payload, lossy: report.lossy };
  }

  return null;
}

/**
 * Hand EventService a copy, not the vendor's own object.
 *
 * The queue holds the object and serializes it at flush, up to 5s later.
 * Elevar reuses and mutates its `ecommerce` objects between pushes, so a
 * shared reference lets a later mutation rewrite an event already counted as
 * sent. Falls back to the original when the payload is not cloneable — worse
 * than a copy, still better than dropping the event.
 */
function detachPayload(payload: Record<string, unknown>): Record<string, unknown> {
  try {
    return structuredClone(payload);
  } catch (error) {
    // Logged, not silent: the fallback hands EventService the vendor's live
    // object, which is precisely the case this function exists to prevent. A
    // payload carrying a function (GTM's `eventCallback` is enough) or a DOM
    // node lands here, and without a line in the console a store where the
    // protection never engages looks identical to one where it does.
    log.warn('structuredClone failed; forwarding the vendor object by reference:', error);
    return payload;
  }
}

function readArray(key: string): unknown[] {
  const value = (window as unknown as Record<string, unknown>)[key];
  return Array.isArray(value) ? value : [];
}

function activeSources(): SourceSpec[] {
  const specs: SourceSpec[] = [];
  if (activeConfig?.elevar) specs.push(SOURCES.elevar);
  if (activeConfig?.gtm) specs.push(SOURCES.gtm);
  return specs;
}

type RegisteredEventService = NonNullable<ReturnType<typeof getEventService>>;

/**
 * Emit the document's single page_view, once delivery is possible.
 *
 * Contained, for the same reason the entry loop is: a `track` that throws here
 * used to abort drain() before a single source was read, and because
 * pageViewSent stays false it threw again every tick — one bad page_view
 * wedged every source for the life of the page. Measured: 11 page_view
 * attempts, zero entries forwarded.
 */
function emitPageViewOnce(service: RegisteredEventService): void {
  if (!activeConfig?.pageView || pageViewSent) return;
  try {
    service.track('page_view', {
      // Sanitised like every other analytics URL in the SDK: a shopper can
      // land on a path carrying a reset token or a session id in the query,
      // and page_location would otherwise ship it verbatim.
      page_location: sanitizeUrl(window.location.href),
      page_path: window.location.pathname,
      page_title: document.title,
    });
    // After the call, not before: a throwing track should be retried next tick
    // rather than silently consuming the page's only page_view.
    pageViewSent = true;
  } catch (error) {
    log.error('page_view could not be forwarded; continuing with sources:', error);
  }
}

/**
 * Event names that carry a completed order.
 *
 * This is the one place the bridge has to know what an event MEANS rather than
 * only forwarding its name, and the reason is narrow: `purchase` is the single
 * canonical event whose backend handler PARSES the payload.
 * `app/tools/events/purchase.py` reads `transaction_id`, `value` and
 * `ecommerce.items`, then APPENDS the id and the SKUs to columns nothing
 * de-duplicates. Every other handler ignores the payload, so a duplicate there
 * costs one redundant row; a duplicate purchase rewrites the conversation's
 * order history as `1234,1234,1234` and triples its SKU list.
 *
 * NOT a spelling map — the backend still owns spelling
 * (`event_name_normalizer.canonical_event_name`). This list decides only which
 * entries get the guard, so a spelling missing from it means a purchase that is
 * not de-duplicated HERE — never one renamed, dropped or re-routed.
 *
 * That gap is real and cannot be closed from the browser: a tenant may map any
 * spelling onto `purchase` through `website_config.event_name_map`, which the
 * bridge cannot see. The backend therefore needs its own guard regardless. This
 * one stops the duplicates we can see, at the only point where the shopper's
 * own storage can tell us the order was already counted on an earlier page.
 */
const PURCHASE_EVENTS = new Set(['purchase', 'dl_purchase']);

/**
 * Where a transaction id hides.
 *
 * GA4 puts it at `ecommerce.transaction_id`; gtag's params object puts it at the
 * root; Elevar and Universal Analytics keep the older
 * `ecommerce.purchase.actionField.id`; UA's classic push spells it
 * `transactionId`; several themes call it `order_id`. The list is searched in
 * order and the first hit wins, so nesting before root — an entry carrying both
 * means the `ecommerce` block is the one the platform filled in deliberately.
 *
 * A shape missing from this list no longer costs the sale: `screenPurchase`
 * forwards a purchase that carries real content but no recognised id, it just
 * cannot de-duplicate it.
 */
const TRANSACTION_ID_PATHS: readonly (readonly string[])[] = [
  ['ecommerce', 'transaction_id'],
  ['ecommerce', 'purchase', 'actionField', 'id'],
  ['ecommerce', 'purchase', 'actionField', 'transaction_id'],
  ['ecommerce', 'actionField', 'id'],
  ['ecommerce', 'order_id'],
  ['transaction_id'],
  ['transactionId'],
  ['order_id'],
  ['orderId'],
];

/**
 * Paths that carry the substance of a sale: money, or things bought.
 *
 * Used only to tell a real purchase from an empty one. An entry with neither is
 * scaffolding wearing the event name; an entry with either is somebody's order,
 * whatever its id is spelled.
 */
const PURCHASE_CONTENT_PATHS: readonly (readonly string[])[] = [
  ['value'],
  ['ecommerce', 'value'],
  ['ecommerce', 'purchase', 'actionField', 'revenue'],
  ['items'],
  ['ecommerce', 'items'],
  ['ecommerce', 'purchase', 'products'],
];

/**
 * Orders already forwarded, and when.
 *
 * A purchase outlives the page that produced it, so `forwarded` cannot guard
 * it: reopening the order-confirmation URL is a new document holding new entry
 * objects, and every reopen would book the order again. This is not
 * hypothetical — another storefront counted one order twice before its theme
 * grew the same guard, and the second count was a shopper pressing back.
 *
 * One record rather than a key per order, so the bridge cannot litter a
 * shopper's storage without bound, pruned on write by both age and count.
 *
 * The window matches EventService's own queue retention, and that is the whole
 * reason for the number. `track()` returning means QUEUED, not delivered: the
 * queue drops an event after `maxRetries` flush failures (`events.ts`) and
 * discards anything older than 24h on the next load. A marker outliving the
 * queue therefore asserts a delivery it cannot know happened — so after a
 * backend outage the sale would be gone AND every later push of that order
 * refused for as long as the marker lasted. Bounding it to the queue's own
 * lifetime makes the worst case one day of refusals, after which reopening the
 * confirmation page can still recover the sale. A duplicate is absorbed
 * downstream; a lost sale is not recoverable anywhere.
 */
const PURCHASE_STORAGE_KEY = 'omniguide_purchases_seen';
const PURCHASE_MAX_AGE_MS = 24 * 60 * 60 * 1000;
const PURCHASE_MAX_TRACKED = 50;

/**
 * In-memory mirror of that record: order id to when it was counted.
 *
 * Module-level for the same reason `forwarded` is: a provider unmounting must
 * not forget which orders were counted. It is also the ONLY guard when storage
 * is unavailable — a private window still pushes `purchase` three times on one
 * page load, and must still forward exactly one.
 *
 * It holds TIMESTAMPS rather than bare ids so the same age window applies here.
 * A plain set never expires, and a document can outlive the window: a pinned
 * tab, a restored session, an SPA storefront. That set would go on refusing an
 * order long after the persisted marker had aged out and EventService had given
 * up on delivering it — silently cancelling the recovery the window exists to
 * provide, and only for the shoppers whose tab stayed open.
 */
let countedPurchases = new Map<string, number>();

function readPath(payload: Record<string, unknown>, path: readonly string[]): unknown {
  let cursor: unknown = payload;
  for (const key of path) {
    if (!cursor || typeof cursor !== 'object') return undefined;
    cursor = (cursor as Record<string, unknown>)[key];
  }
  return cursor;
}

/**
 * The order's id, or null when the entry identifies no order.
 *
 * Numbers are accepted and stringified: an order number is an identifier, and
 * plenty of platforms push it unquoted. `0` is not special-cased away — it is a
 * finite number and some counters legitimately start there.
 */
function transactionIdOf(payload: Record<string, unknown>): string | null {
  for (const path of TRANSACTION_ID_PATHS) {
    const value = readPath(payload, path);
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  }
  return null;
}

/** Whether this entry describes an actual sale rather than an empty shell. */
function purchaseHasContent(payload: Record<string, unknown>): boolean {
  return PURCHASE_CONTENT_PATHS.some(path => {
    const value = readPath(payload, path);
    if (Array.isArray(value)) return value.length > 0;
    if (typeof value === 'number') return Number.isFinite(value);
    if (typeof value === 'string') return value.trim().length > 0;
    return false;
  });
}

/**
 * `window.localStorage`, or null when it cannot be touched at all.
 *
 * `typeof localStorage === 'undefined'` is NOT enough, and the difference costs
 * sales. `typeof` only guards an UNDECLARED identifier; here the identifier is
 * declared and reading it runs a getter, which throws `SecurityError` in Safari
 * with cookies blocked and in a partitioned third-party iframe. That throw
 * escapes the guard, unwinds through `drainSource`'s catch, and the entry is
 * already in `forwarded` — so the purchase is dropped rather than forwarded
 * un-de-duplicated, which is the opposite of the intended failure direction.
 */
function purchaseStore(): Storage | null {
  try {
    return typeof localStorage === 'undefined' ? null : localStorage;
  } catch {
    return null;
  }
}

/**
 * Stored orders, minus anything past the age window.
 *
 * Returns null when the record could not be READ — unreadable is not the same
 * as empty. Treating a transient failure as "no orders counted" would let the
 * next write replace every remembered order with a single-entry record, so one
 * bad read quietly forgets the rest.
 */
function loadPurchaseRecord(): Record<string, number> | null {
  const store = purchaseStore();
  if (!store) return null;
  try {
    const stored = store.getItem(PURCHASE_STORAGE_KEY);
    if (!stored) return Object.create(null) as Record<string, number>;
    const parsed: unknown = JSON.parse(stored);
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null;
    const cutoff = Date.now() - PURCHASE_MAX_AGE_MS;
    // A null-prototype object: an order id of `__proto__` would otherwise hit
    // the prototype setter and never persist, so that order would re-forward on
    // every later page load.
    const fresh: Record<string, number> = Object.create(null);
    for (const [id, at] of Object.entries(parsed as Record<string, unknown>)) {
      if (typeof at === 'number' && at > cutoff) fresh[id] = at;
    }
    return fresh;
  } catch (error) {
    log.warn('Could not read the forwarded-purchase record:', error);
    return null;
  }
}

function purchaseAlreadyCounted(txId: string): boolean {
  const cutoff = Date.now() - PURCHASE_MAX_AGE_MS;
  const countedAt = countedPurchases.get(txId);
  if (countedAt !== undefined && countedAt > cutoff) return true;

  const record = loadPurchaseRecord();
  // An unreadable record means "not known to be counted": risking a duplicate
  // is the right way to fail, since the alternative is refusing a real sale.
  return record !== null && Object.prototype.hasOwnProperty.call(record, txId);
}

function markPurchaseCounted(txId: string): void {
  const cutoff = Date.now() - PURCHASE_MAX_AGE_MS;
  for (const [id, at] of countedPurchases) {
    if (at <= cutoff) countedPurchases.delete(id);
  }
  countedPurchases.set(txId, Date.now());
  const store = purchaseStore();
  const record = loadPurchaseRecord();
  // Not writing over a record we could not read — see loadPurchaseRecord.
  if (!store || record === null) return;

  record[txId] = Date.now();
  const newestFirst = Object.entries(record)
    .sort(([, a], [, b]) => b - a)
    .slice(0, PURCHASE_MAX_TRACKED);
  try {
    store.setItem(PURCHASE_STORAGE_KEY, JSON.stringify(Object.fromEntries(newestFirst)));
  } catch (error) {
    // Counted in memory but not on disk: this page stays correct, a later
    // reopen of the same order does not. Better than throwing mid-drain.
    log.warn('Could not persist the forwarded-purchase record:', error);
  }
}

/**
 * What the purchase guard decides about one entry.
 *
 * Deciding and RECORDING are separate on purpose. The record is written only
 * once EventService has actually taken the event (see `drainSource`): marking
 * first would let a `track` that throws burn the order id, so the retry A LATER
 * PAGE LOAD would otherwise get is refused for an event that was never
 * delivered. The failed entry object itself is never retried — it is already in
 * `forwarded` — so the retry is always a fresh push of the same order. The
 * bridge already treats an attempted entry as consumed for `forwarded`, but
 * that costs one event; burning an order id costs the sale.
 */
interface PurchaseClaim {
  /** Whether the entry may be forwarded at all. */
  forward: boolean;
  /** The order to record once the hand-off has succeeded, if this is one. */
  txId: string | null;
}

/**
 * Screen one entry against the purchase guard.
 *
 * Non-purchases pass untouched, carrying no order to record. A purchase must
 * both identify its order and not already have been counted — the same rule
 * that refuses the second push in this tick refuses a reopen tomorrow, because
 * both consult the same record.
 *
 * An EMPTY purchase is refused — no id, no value, no items. Measured on a live
 * storefront: one order pushes `purchase` THREE times on a single page load,
 * one entry carrying the id, the value and nine `ecommerce` keys, and two
 * carrying none of them. The two are container scaffolding wearing the event
 * name; forwarding them books a conversion that cannot be attributed to an
 * order and reaches `purchase.py` as a sale worth nothing.
 *
 * A purchase carrying content but no RECOGNISED id is forwarded anyway, with a
 * warning, and simply cannot be de-duplicated. Do NOT tighten this back to
 * "refuse every id-less purchase": a storefront spelling its id outside
 * `TRANSACTION_ID_PATHS` would then have every sale dropped in silence, which is
 * far worse than the duplicate the guard exists to prevent.
 */
function screenPurchase(parsed: ParsedEntry): PurchaseClaim {
  if (!PURCHASE_EVENTS.has(parsed.name.toLowerCase())) return { forward: true, txId: null };

  const txId = transactionIdOf(parsed.payload);
  if (!txId) {
    // Only an EMPTY purchase is refused. Refusing every id-less one was far too
    // broad: a storefront spelling its id somewhere this list does not know
    // would have every sale dropped in silence, which is a worse outcome than
    // the duplicate the guard exists to prevent.
    // `!parsed.lossy` first: an entry looks empty when its payload could not
    // be READ, and refusing that drops a real sale to guard against a duplicate
    // that was never there. Emptiness only means "nothing was sent" when we
    // actually managed to read what was sent.
    if (!parsed.lossy && !purchaseHasContent(parsed.payload)) {
      log.warn(`Refusing an empty ${parsed.name} entry: no transaction id, value or items`);
      return { forward: false, txId: null };
    }
    if (parsed.lossy) {
      log.warn(
        `Forwarding a ${parsed.name} whose payload could not be fully read; `
        + 'it looks empty but may not be. Never refuse a sale on an unread payload.',
      );
    }
    log.warn(
      `Forwarding a ${parsed.name} with no recognised transaction id; ` +
      'it cannot be de-duplicated. Add its id path to TRANSACTION_ID_PATHS.',
    );
    return { forward: true, txId: null };
  }
  if (purchaseAlreadyCounted(txId)) {
    log.debug(`Order ${txId} was already forwarded; skipping this ${parsed.name}`);
    return { forward: false, txId: null };
  }
  return { forward: true, txId };
}

/**
 * ── The dual-spelling guard ────────────────────────────────────────
 *
 * A dual-tagged theme emits BOTH spellings of one action: `add_to_cart` and
 * `addToCart` land in the array as two distinct objects carrying two distinct
 * names. `forwarded` tracks object IDENTITY, so both pass, and every
 * engagement metric built on them doubles — add-to-cart, view-item, and the
 * denominators of CTR and conversion with them. `purchase` was already covered
 * (see `PURCHASE_EVENTS`) because a duplicate there corrupts an order record;
 * the rest only inflate counts, so nothing surfaced them.
 *
 * Two entries are the same occurrence when they carry the same folded name,
 * the same payload, and DIFFERENT original spellings, inside a short window.
 *
 * That last clause is the whole design. A second push of the SAME spelling is
 * always forwarded, because a theme emits one push per spelling per action: a
 * spelling arriving twice is the shopper acting twice, not the theme tagging
 * twice. So the thing this guard must never do — swallow a real second
 * add-to-cart — is prevented by the rule itself rather than by the window
 * being lucky, and `drainSource` cannot tell a push 900ms ago from one 9ms ago
 * because both are observed in the same poll.
 *
 * What it costs: a theme that emits the identical spelling twice for one
 * action is not de-duplicated here, and a genuine repeat that somehow arrives
 * under the OTHER spelling is suppressed. The first is a different defect; the
 * second would require a theme to alternate spellings between two adds of one
 * item. Both sit on the safe side of "the guard may cost a duplicate; it must
 * never cost a real event".
 */

/**
 * How long an entry can still be the other half of a pair.
 *
 * Both spellings come from one handler, so the pair is normally read by a
 * single drain pass — microseconds apart — and at worst is split across two
 * when a tick boundary falls between the two pushes. One poll interval covers
 * that split, because the two passes are one interval apart.
 *
 * Kept to the minimum that works, because this window is where the guard's
 * remaining risk lives. The same-spelling rule protects a repeat under the
 * same name, but nothing protects a theme whose containers have DIFFERENT
 * trigger coverage — the legacy tag on the PDP form, the modern one on
 * quick-add — where one action emits one spelling and the spelling alternates
 * between actions. Two such adds of the same product inside the window read
 * exactly like one dual-tagged add, and the second is lost. Nothing observable
 * at drain time separates them: entries are seen when the poll runs, not when
 * they were pushed, so a push 900ms ago and one 9ms ago carry the same
 * `Date.now()`. Every millisecond of window is exposure to that case, so there
 * are no spare ones.
 *
 * A hidden tab throttles `setInterval` to roughly once a minute, so a pair
 * split across a boundary there is seen long after this expires and both
 * forward. That is a duplicate, which is the acceptable direction.
 */
const DEDUPE_WINDOW_MS = POLL_INTERVAL_MS;

/**
 * Most keys remembered at once.
 *
 * The age prune cannot run part-way through a synchronous pass, and the
 * tab-hide drain is unbounded — a 300-entry backlog lands in one millisecond
 * with nothing yet stale to prune. This caps that burst. Evicting the oldest
 * key costs at most a duplicate, which is the direction this guard may fail in.
 *
 * Matches `PURCHASE_MAX_TRACKED` rather than being generous, because each key
 * holds a SERIALIZED PAYLOAD and a quiet page keeps whatever it last pruned
 * to. `forwarded` is a WeakSet precisely so it cannot pin vendor payloads; this
 * map can, so it is kept small enough that it does not matter. A one-second
 * window holds a handful of events on any real storefront — 50 is already
 * tail cover.
 */
const DEDUPE_MAX_TRACKED = 50;

/** One occurrence: when it was forwarded, and the spellings seen for it. */
interface Occurrence {
  at: number;
  names: Set<string>;
}

/**
 * Most occurrences of ONE key held open at once.
 *
 * A list rather than a single record, because the sources are drained one
 * array at a time: `activeSources()` empties Elevar before it starts on GTM,
 * so a storefront tagged across BOTH containers delivers two actions as
 * B,B,A,A rather than interleaved. Holding one occurrence per key, the second
 * A found the only open occurrence already carrying its own spelling and
 * counted as new — three events for two actions, on exactly the dual-tagged
 * shape this guard exists for.
 *
 * The cost is stated plainly: an alias can now be matched against an older
 * unmatched occurrence rather than only the most recent, so a genuinely new
 * event under a second spelling has more open occurrences that might absorb
 * it. The window still bounds how far back that reaches, and a spelling an
 * occurrence already carries still never matches it, so a repeat under the
 * same name is as safe as before.
 *
 * Ten is tail cover: it is how many pushes of ONE event, with an identical
 * payload, can be waiting for their pair inside a single second. Dropping the
 * oldest past that costs a duplicate.
 */
const DEDUPE_MAX_OPEN = 10;

/**
 * Occurrences seen recently, keyed by content, oldest first within each key.
 *
 * Module-level for the reason `forwarded` is: a provider unmounting mid-session
 * must not reopen the window on events already sent.
 */
let recentEvents = new Map<string, Occurrence[]>();

/**
 * Fold one spelling to its comparison shape — case and separators, nothing else.
 *
 * KEY ONLY. See the file header: what reaches EventService is still exactly
 * the name the storefront pushed. This decides whether two entries are the
 * same occurrence, never what an event is called, so it cannot drift away from
 * the backend's normalizer the way an alias table would — there is nothing
 * here to maintain. `addToCart`, `add_to_cart` and `Add-To-Cart` fold together
 * because they differ only in shape.
 *
 * A vendor PREFIX (`dl_add_to_cart` against `add_to_cart`) deliberately does
 * NOT fold. Stripping it is vocabulary, not shape, and vocabulary belongs to
 * the backend. The cost of leaving it is a collapse we miss — a duplicate —
 * not an event we lose.
 */
function foldEventName(name: string): string {
  const lower = name.toLowerCase();
  // `||` rather than a bare return: a name made only of separators folds to
  // the empty string, which would make every such name key alike.
  return lower.replace(/[^\p{L}\p{N}]+/gu, '') || lower;
}

/**
 * Fields that are bookkeeping about a PUSH rather than data about the event.
 *
 * Without this the guard is inert on the source it was written for. GTM stamps
 * `gtm.uniqueEventId` onto each message it processes, and it is a per-push
 * counter — so the two spellings of one action carry two different values, the
 * payloads differ, and nothing collapses. `event_id` does the same job for
 * Meta's CAPI de-duplication and rides on every Elevar `dl_*` event, and a
 * store running two tag containers is exactly a store that stamps one.
 * `eventCallback` and `eventTimeout` are GTM's own controls.
 *
 * Excluded from the KEY only — unlike `DROPPED_KEYS` these still reach the
 * backend, because they are the storefront's data to send even though they
 * cannot help decide whether two entries are the same occurrence.
 *
 * Not the alias table the file header refuses: it maps no name to any other
 * name. It names fields that are unique per push BY CONSTRUCTION, so a vendor
 * added here can never be a vendor whose vocabulary we have to track.
 */
const PER_PUSH_KEYS = new Set(['event_id', 'eventId', 'eventCallback', 'eventTimeout']);

function isPerPushNoise(key: string): boolean {
  // Prefix for GTM's namespace, which is all internal bookkeeping, so a new
  // `gtm.*` field cannot quietly defeat the key the way `uniqueEventId` did.
  return key.startsWith('gtm.') || PER_PUSH_KEYS.has(key);
}

/**
 * Serialize a payload so key ORDER cannot decide identity.
 *
 * The two spellings of one action are often built by two different tag
 * templates, and plain `JSON.stringify` would call `{a,b}` and `{b,a}`
 * different events. Sorting at every level removes that. Throws on a payload
 * it cannot walk, which the caller turns into "forward it unguarded".
 *
 * A `Date` is read as its instant. The other opaque built-ins (`Map`, `Set`,
 * `RegExp`, the weak collections) throw rather than serialize: `stripValue`
 * passes them through by reference, and `Object.entries` finds nothing on any
 * of them, so every `Map` would key as `{}` and two different ones would
 * collapse. Functions and symbols throw for the same reason — they
 * stringify to `undefined`, which would key as `null`. Refusing to key any
 * of them forwards both, which is the direction this guard fails in.
 */
function stableStringify(value: unknown): string {
  // A function or a symbol stringifies to `undefined`, which the fallback
  // below would turn into the key a real `null` produces — while the wire
  // payloads differ, because the queue's serialization DROPS a function
  // property and KEEPS a null one. Refused for the same reason the opaque
  // built-ins are: an event we cannot tell apart must not be collapsed.
  if (typeof value === 'function' || typeof value === 'symbol') {
    throw new TypeError('a function or symbol value is not keyable');
  }
  if (!value || typeof value !== 'object') return JSON.stringify(value) ?? 'null';
  if (value instanceof Date) return JSON.stringify(value.toISOString());
  if (OPAQUE.some(ctor => value instanceof ctor)) throw new TypeError('opaque value is not keyable');
  // `Array.from`, not `map`: `map` preserves a HOLE, `join` renders it as
  // nothing, and `new Array(1)` would key identically to `[]` — while the
  // queue sends them as `[null]` and `[]`. Two differently spelled events
  // with those payloads would lose the second. `Array.from` materializes a
  // hole as `undefined`, which keys as `null`, matching JSON's own reading.
  if (Array.isArray(value)) return `[${Array.from(value, stableStringify).join(',')}]`;
  const entries = Object.entries(value as Record<string, unknown>)
    .filter(([key, child]) => child !== undefined && !isPerPushNoise(key))
    .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
  return `{${entries.map(([k, v]) => `${JSON.stringify(k)}:${stableStringify(v)}`).join(',')}}`;
}

/**
 * The content key for one entry, or null when the entry cannot be keyed.
 *
 * Content rather than object identity, which is the whole point: an alias and
 * its modern spelling are two distinct objects, so `forwarded` lets both pass.
 *
 * An unkeyable payload is forwarded with a warning rather than held: a BigInt,
 * a throwing getter, an opaque built-in. (NOT a cycle — `stripDroppedKeys`
 * always resolves those to `undefined` before anything gets here.) This guard
 * exists to drop duplicates, so its own failure must be to stop guarding,
 * never to stop forwarding.
 */
function dedupeKeyOf(parsed: ParsedEntry): string | null {
  try {
    // NUL separates the two halves: no event name contains it, so no
    // name-and-payload pair can be reassembled into another pair's key.
    return `${foldEventName(parsed.name)}\u0000${stableStringify(parsed.payload)}`;
  } catch (error) {
    log.warn(`Forwarding ${parsed.name} unguarded; its payload could not be keyed:`, error);
    return null;
  }
}

/** Whether this occurrence is still inside the window. */
function isOpen(occurrence: Occurrence, now: number): boolean {
  // An occurrence dated in the FUTURE is a wall clock that stepped backwards —
  // an NTP correction, a resumed VM. Treated as expired rather than as freshly
  // seen, because the alternative pins it open until the clock catches up and
  // suppresses every alias that arrives meanwhile.
  return occurrence.at <= now && now - occurrence.at <= DEDUPE_WINDOW_MS;
}

/** This key's occurrences that are still open, writing the pruned list back. */
function openOccurrences(key: string): Occurrence[] {
  const held = recentEvents.get(key);
  if (!held) return [];
  const now = Date.now();
  const open = held.filter(occurrence => isOpen(occurrence, now));
  if (open.length) recentEvents.set(key, open);
  else recentEvents.delete(key);
  return open;
}

/**
 * Whether this entry is a second SPELLING of an occurrence already forwarded.
 *
 * A spelling already seen is a new occurrence and returns false — that is the
 * rule that keeps a shopper's second add-to-cart.
 *
 * Records the alias on its way out, which DOES change later decisions: a third
 * entry under that same spelling now forwards. That is deliberate and it is the
 * safe direction — a spelling this occurrence has already accounted for can
 * only be a new occurrence. The refusal itself is final for this entry, since
 * `forwarded` already holds it.
 */
function isAliasOfForwarded(key: string, name: string): boolean {
  // Oldest first: the occurrence that has waited longest for its pair is the
  // likeliest to be missing it, and matching it first leaves the newer ones
  // free for the spellings still to come in this batch.
  const waiting = openOccurrences(key).find(occurrence => !occurrence.names.has(name));
  if (!waiting) return false;
  waiting.names.add(name);
  return true;
}

/**
 * Record a forward: a new occurrence opens, known so far by this spelling only.
 *
 * It is APPENDED rather than merged into an open one, so each push is dated
 * from itself — a run of repeats cannot ratchet one occurrence forward
 * indefinitely and start swallowing the spellings of later ones — and so a
 * batch of repeats leaves one slot per push for the aliases still to arrive.
 */
function markRecentlyForwarded(key: string, name: string): void {
  const now = Date.now();
  for (const [seen, held] of recentEvents) {
    if (!held.some(occurrence => isOpen(occurrence, now))) recentEvents.delete(seen);
  }
  const open = openOccurrences(key);
  open.push({ at: now, names: new Set([name]) });
  // Deleted BEFORE the cap is enforced, for two reasons. A Map keeps a re-set
  // key in its original position, so without the delete the prune below evicts
  // the freshest key rather than the stalest. And adding to a key already
  // present does not grow the map, so enforcing the cap first would evict an
  // unrelated key that had done nothing wrong — costing a duplicate when its
  // own alias arrives — and leave the record one short besides.
  recentEvents.delete(key);
  while (recentEvents.size >= DEDUPE_MAX_TRACKED) {
    const oldest: string | undefined = recentEvents.keys().next().value;
    if (oldest === undefined) break;
    recentEvents.delete(oldest);
  }
  recentEvents.set(key, open.slice(-DEDUPE_MAX_OPEN));
}

/** What both guards together decide about one entry. */
interface EntryClaim extends PurchaseClaim {
  /** The content key to record once the hand-off has succeeded, if keyable. */
  dedupeKey: string | null;
}

/**
 * Screen one entry: the purchase guard first, then the dual-spelling guard.
 *
 * Order matters, and the second does not replace the first. `purchase` keeps
 * its stricter screening — an order id checked against a record that outlives
 * the page — so a purchase refused there never reaches this window at all, and
 * one that passes is still recorded by transaction id afterwards.
 */
function screenEntry(parsed: ParsedEntry): EntryClaim {
  const order = screenPurchase(parsed);
  if (!order.forward) return { ...order, dedupeKey: null };

  // An entry we could not fully read is forwarded but NEVER keyed.
  //
  // The key is built from the payload, so a entry missing a field is a key
  // missing a field — and two genuinely different actions whose only
  // distinguishing value was the unreadable one would produce the same key.
  // The second would then be discarded as a spelling of the first: a readable
  // event lost to protect against a duplicate that was never a duplicate.
  // A null key skips the alias lookup here AND records nothing for the next
  // entry to match against, so the damage cannot spread in either direction.
  //
  // This is the same disposition `dedupeKeyOf` already takes when stringifying
  // throws: forward it, do not fold it. AC5's "forwards with a warning" is
  // exactly this case — an entry that cannot be keyed is not a duplicate, it
  // is an unknown.
  if (parsed.lossy) {
    log.warn(
      `Forwarding ${parsed.name} without de-duplication:`
      + ' part of the entry could not be read, so it cannot be compared to another.',
    );
    return { ...order, dedupeKey: null };
  }

  const dedupeKey = dedupeKeyOf(parsed);
  if (dedupeKey !== null && isAliasOfForwarded(dedupeKey, parsed.name)) {
    log.debug(`Skipping ${parsed.name}: another spelling of it was just forwarded`);
    return { forward: false, txId: null, dedupeKey: null };
  }
  return { ...order, dedupeKey };
}

/**
 * Forward one source's unseen entries, returning the budget left over.
 *
 * An entry is marked forwarded BEFORE the track call, not after: an entry that
 * throws has still been attempted, and retrying it every tick would wedge this
 * source — and every source after it — for the life of the page.
 *
 * Entries are additionally screened (`screenEntry` — the purchase guard, then
 * the dual-spelling guard) between the source's own skip filter and the budget,
 * so a refused one neither reaches EventService nor displaces an entry that
 * would have. A refusal is final for that object, because marking happens
 * first — correct for the empty shells and the second spellings it targets.
 */
function drainSource(
  spec: SourceSpec,
  service: RegisteredEventService,
  budget: number,
): number {
  let left = budget;
  for (const entry of readArray(spec.key)) {
    if (left <= 0) return 0;
    if (!entry || typeof entry !== 'object') continue;
    if (forwarded.has(entry)) continue;
    forwarded.add(entry);
    try {
      const parsed = parseEntry(entry);
      if (!parsed) continue;
      if (spec.skip?.(parsed.name)) continue;
      // Screened before the budget is charged: a refused entry consumed no
      // track call, so it must not displace an entry that would have made one.
      const claim = screenEntry(parsed);
      if (!claim.forward) continue;
      // Decremented BEFORE the call: a throwing entry still consumed an
      // attempt, and leaving it free let one tick blow past the cap entirely
      // (60 throwing entries ahead of 60 good ones made 110 calls against a
      // budget of 50) — the unpaced burst the cap exists to prevent, arriving
      // on exactly the day EventService is the thing misbehaving.
      left--;
      // VERBATIM: `parsed.name`, never the folded key — folding never reaches the wire.
      service.track(parsed.name, detachPayload(parsed.payload));
      // Both records are written after the hand-off, never before — see
      // PurchaseClaim. A `track` that throws must not burn the key, or the
      // order id, that its retry would arrive under.
      // The order id first: if either record ever threw, the one whose absence
      // double-books a sale must already be written.
      if (claim.txId) markPurchaseCounted(claim.txId);
      if (claim.dedupeKey) markRecentlyForwarded(claim.dedupeKey, parsed.name);
    } catch (error) {
      log.error(`Skipping unforwardable entry on ${spec.key}:`, error);
    }
  }
  return left;
}

/**
 * Forward everything not yet seen on each source.
 *
 * Nothing is marked until an EventService exists to hand events to.
 * `trackEvent` is a no-op while the registry is empty, so marking entries we
 * could not deliver would drop them with no queue and no retry. Holding them
 * instead makes the bridge's start time irrelevant: it replays the whole array
 * whenever delivery becomes possible.
 */
function drain(unbounded = false): void {
  const service = getEventService();
  if (!service) return;

  emitPageViewOnce(service);

  // The cap bounds a poll tick, where the remainder genuinely does go next
  // tick. On the way out there is no next tick, so the budget would not pace
  // the work — it would discard the tail with the page. Measured before this:
  // a 300-entry backlog at tab-hide forwarded 50 and lost 250.
  let budget = unbounded ? Number.POSITIVE_INFINITY : MAX_FORWARDS_PER_TICK;
  for (const spec of activeSources()) {
    budget = drainSource(spec, service, budget);
    if (budget <= 0) return;
  }
}

function tick(unbounded = false): void {
  try {
    drain(unbounded);
  } catch (error) {
    log.error('Drain failed:', error);
  }
  // Re-read rather than trusting what drain saw: a drain that THREW has told
  // us nothing about whether a sink exists, and counting that as an idle tick
  // would stand down a page that is merely failing.
  //
  // Reset rather than merely skipped, so the count stays CONSECUTIVE. A
  // lifetime total would stand the bridge down one tick after a sink that had
  // been delivering for an hour went away, instead of giving it the full
  // deadline it gives a page that never had one.
  if (getEventService()) {
    idleTicks = 0;
    return;
  }
  if (++idleTicks >= MAX_IDLE_TICKS) standDown();
}

/**
 * Stop polling a page that has shown no sink, and arm the wake-up.
 *
 * The subscription is what makes this reversible, and it is subscribed only
 * here: a bridge that stood down is indistinguishable from one that never
 * started unless something tells it a sink arrived. Nothing is forgotten —
 * `forwarded` and the backlog are untouched, so a provider that mounts a
 * minute late still replays the whole array.
 */
function standDown(): void {
  clearPolling();
  log.debug(`No EventService after ${MAX_IDLE_TICKS} ticks; polling paused until one registers.`);
  awaitingRegistration ??= onEventServiceRegistered(() => { startPolling(); });
}

function startPolling(): void {
  // Before the guard: a fresh attach is evidence a sink may yet arrive, and it
  // should buy the full deadline even when the poller is already running.
  idleTicks = 0;
  if (intervalId !== null || refCount <= 0) return;
  stopLifecycleListeners = listenForPageEnd();
  intervalId = window.setInterval(tick, POLL_INTERVAL_MS);
  tick();
}

/**
 * Send what the final drain just handed over, instead of trusting listener order.
 *
 * EventService registers its own `visibilitychange` beacon in its CONSTRUCTOR,
 * and the page builds the sink before starting the bridge — so that beacon
 * runs first, flushes an empty queue, and is gone by the time this drain adds
 * anything. Reordering the two would fix the common case and leave the rest:
 * a bridge that stood down and resumed re-registers its listener LAST, behind
 * an EventService that has been there since page load.
 *
 * `track` does kick a keepalive fetch of its own a microtask later, which
 * usually wins. Usually is not a guarantee: that kick bails outright when a
 * flush is already in flight, and then the entry has missed both the beacon
 * and its own send, with nothing left before teardown.
 *
 * Costs nothing when there is nothing to send — `sendBeacon` returns early on
 * an empty queue, and a successful one empties it, so a second
 * `visibilitychange` cannot send the same entry again.
 */
/**
 * Catch everything pushed since the last poll, and send it.
 *
 * The last reliable moment before the page goes away, which is why the drain
 * is unbounded here: there is no next tick to carry a remainder.
 *
 * Idempotent, and it has to be — both signals below can fire for one
 * departure. A second run finds every entry already in `forwarded`, and
 * `sendBeacon` returns early on the queue the first one emptied.
 */
function finalDrain(): void {
  tick(true);
  beaconFinalDrain();
}

/**
 * Listen for the page ending, on BOTH signals, because neither covers it alone.
 *
 * `visibilitychange` is the one that fires when a tab is merely backgrounded,
 * which is often the last moment a phone gives us. But a page can end at
 * `pagehide` with no visibility transition at all — Safari has historically
 * done exactly that — and listening only for the former means the entries
 * pushed since the last poll are never drained, let alone sent. EventService
 * listens for both for the same reason; the bridge has to match it, or its
 * queue is simply missing the newest entries when the beacon goes.
 */
function listenForPageEnd(): () => void {
  const onVisibilityChange = (): void => {
    if (document.visibilityState === 'hidden') finalDrain();
  };
  document.addEventListener('visibilitychange', onVisibilityChange);
  window.addEventListener('pagehide', finalDrain);
  return () => {
    document.removeEventListener('visibilitychange', onVisibilityChange);
    window.removeEventListener('pagehide', finalDrain);
  };
}

function beaconFinalDrain(): void {
  const service = getEventService();
  if (!service) return;
  try {
    service.sendBeacon();
  } catch (error) {
    // The drain is the valuable half and has already happened; its entries are
    // persisted either way. A transport that throws must not lose that.
    log.error('Could not beacon the final drain:', error);
  }
}

function clearPolling(): void {
  if (intervalId !== null) window.clearInterval(intervalId);
  if (stopLifecycleListeners) stopLifecycleListeners();
  intervalId = null;
  stopLifecycleListeners = null;
}

function stopPolling(): void {
  clearPolling();
  // Dropped with the poller: a detached bridge that kept listening would
  // resurrect its own interval the moment any page registered a service.
  if (awaitingRegistration) awaitingRegistration();
  awaitingRegistration = null;
  idleTicks = 0;
  activeConfig = null;
}

/**
 * Whether this config asks the bridge to watch anything at all.
 *
 * Exported because the flags, not the object, decide: `{}` and
 * `{gtm: false}` are configuration that means "off", and a caller setting up
 * the bridge's SINK has to reach the same verdict `startDataLayerBridge` will.
 * Asking here rather than re-deriving it is what stops a storefront that
 * deliberately disabled the bridge from getting an EventService — a flush
 * interval and unload listeners — in exchange for nothing.
 */
export function isDataLayerBridgeEnabled(
  config?: DataLayerBridgeConfig | null,
): config is DataLayerBridgeConfig {
  return Boolean(config && (config.elevar || config.gtm || config.pageView));
}

/**
 * Start forwarding storefront dataLayer events. Returns a detach function.
 *
 * Safe to call once per caller: the poller is refcounted, so the LAST detach
 * stops it rather than the first. Each caller's detach is its own and is
 * idempotent — one caller detaching can neither stop another's bridge nor
 * orphan a live interval.
 *
 * Off by default and opt-in per flag, because a theme that already ships its
 * own dataLayer interceptor would otherwise deliver every event twice.
 */
export function startDataLayerBridge(config: DataLayerBridgeConfig): () => void {
  if (typeof window === 'undefined') return () => {};
  if (!isDataLayerBridgeEnabled(config)) return () => {};

  // First caller wins. Every provider on the page is handed the same config
  // object by auto-init, so there is nothing to merge.
  activeConfig ??= config;
  refCount++;

  // Also the way a stood-down bridge restarts, and it resets the idle deadline
  // either way: a fresh attach is evidence that a sink may yet arrive.
  startPolling();

  let detached = false;
  return () => {
    if (detached) return;
    detached = true;
    refCount--;
    if (refCount <= 0) {
      refCount = 0;
      stopPolling();
    }
  };
}

/**
 * @internal Stop the bridge and clear ALL module state (for testing only).
 *
 * This also deletes `localStorage['omniguide_purchases_seen']`, which is the
 * SHOPPER's record rather than module state: calling it on a live page makes
 * every previously counted order forwardable again. It is exported from the
 * built package, so that is worth knowing before reaching for it outside a test.
 */
export function _resetDataLayerBridge(): void {
  stopPolling();
  refCount = 0;
  forwarded = new WeakSet();
  countedPurchases = new Map();
  recentEvents = new Map();
  try {
    if (typeof localStorage !== 'undefined') localStorage.removeItem(PURCHASE_STORAGE_KEY);
  } catch {
    // Test-only teardown; a storage that refuses to clear is not worth a throw.
  }
  pageViewSent = false;
}
