/**
 * Global EventService registry.
 *
 * Allows the bundle to expose `window.Omniguide.trackEvent()` that delegates
 * to whatever EventService instance is currently active (created by
 * `ensurePageEventService`, at page level or from OmniguideProvider).
 *
 * Theme interceptors call `Omniguide.trackEvent(name, data)` for eCommerce
 * events — this registry routes to the active EventService.
 */

import { createScopedLogger } from './logger.js';
import type { EventService } from './services/events.js';
import type { ConsentService, ConsentState } from './services/consent.js';

const log = createScopedLogger('EventRegistry');

let instance: EventService | null = null;
let consentInstance: ConsentService | null = null;

type RegistrationListener = (service: EventService) => void;
const registrationListeners = new Set<RegistrationListener>();

/**
 * Register the active EventService instance, or null to empty the registry.
 *
 * Called by `ensurePageEventService` — directly, or via OmniguideProvider.
 * Listeners are told about arrivals only, since there is nothing to do about
 * a departure.
 */
export function registerEventService(service: EventService | null): void {
  instance = service;
  if (!service) return;
  // Copied first: a listener is allowed to unsubscribe itself while being
  // called, which would otherwise mutate the set mid-iteration.
  for (const listener of [...registrationListeners]) {
    // Contained individually. This fan-out runs inside OmniguideProvider's
    // render, so an unrelated listener that throws would otherwise fail the
    // provider — and skip every listener queued behind it.
    try {
      listener(service);
    } catch (error) {
      log.error('An EventService registration listener threw:', error);
    }
  }
}

/**
 * Be told when an EventService becomes available. Returns an unsubscribe.
 *
 * This exists so a consumer that found no sink can stop working WITHOUT having
 * to decide that no sink will ever exist. The dataLayer bridge uses it to stop
 * polling a page that has nothing to deliver to, and to start again if a
 * late-mounting provider proves it wrong.
 */
export function onEventServiceRegistered(listener: RegistrationListener): () => void {
  registrationListeners.add(listener);
  return () => { registrationListeners.delete(listener); };
}

/**
 * Get the registered EventService, or null if none registered yet.
 */
export function getEventService(): EventService | null {
  return instance;
}

/**
 * Track an event via the registered EventService.
 * No-op if no EventService is registered yet.
 *
 * This is the function exposed as `window.Omniguide.trackEvent()`.
 */
export function trackEvent(eventName: string, data: Record<string, unknown> = {}): void {
  if (!instance) return;
  instance.track(eventName, data);
}

/**
 * Update context on the registered EventService.
 * No-op if no EventService is registered yet.
 */
export function updateEventContext(updates: {
  sessionId?: string;
  /** `undefined` leaves it alone; `null` CLEARS it. See `EventService.updateContext`. */
  conversationId?: string | null;
  messageId?: string;
  websiteId?: string;
}): void {
  if (!instance) return;
  instance.updateContext(updates);
}

/**
 * Register the active ConsentService instance, or null to empty the registry.
 * Called by `ensurePageEventService`.
 */
export function registerConsentService(service: ConsentService | null): void {
  consentInstance = service;
}

/**
 * Get the registered ConsentService, or null if none registered yet.
 *
 * Exposed so a second creator can REUSE the page's consent service rather than
 * building a rival one: consent is read from the page, but the sync-to-backend
 * state is per instance, so two of them would each sync the same consent.
 */
export function getConsentService(): ConsentService | null {
  return consentInstance;
}

/**
 * Get the current consent state for debugging.
 * Returns null if no ConsentService is registered yet.
 *
 * Exposed as `window.Omniguide.getConsentState()`.
 */
export function getConsentState(): ConsentState | null {
  if (!consentInstance) return null;
  return consentInstance.getState();
}
