/**
 * Shared URL-safety helpers (headless / SSR-safe).
 *
 * Two distinct concerns:
 *  - `sanitizeUrl` — strip query + fragment before a URL goes into an analytics
 *    payload or backend request, so host query strings (PHPSESSID, OAuth tokens,
 *    reset keys, gclid, campaign ids) don't leak and don't fragment edge-cache keys.
 *  - `isSafeNavigationUrl` / `safeHref` — scheme allow-list for backend-supplied
 *    links, so a poisoned API/cache response containing `javascript:` (etc.) can't
 *    execute on click.
 *
 * Lives in core so every package (catalog, carousel, product-list, react) can share
 * one implementation. `packages/react/src/utils/navigation.ts` predates this and keeps
 * its own copy for back-compat (it's part of react's public API); prefer these going
 * forward.
 */

const SAFE_PROTOCOLS = ['http:', 'https:'];

/**
 * The current page origin, or `undefined` when there is no DOM (SSR / tests).
 * Used as the default base for resolving relative URLs.
 */
function defaultBase(): string | undefined {
  return typeof window !== 'undefined' && window.location ? window.location.origin : undefined;
}

/**
 * Strip query string and fragment from a URL — returns `origin + pathname` only.
 * Falls back to the original string on parse failure (and `''` for empty input).
 */
export function sanitizeUrl(raw: string): string {
  if (!raw) return '';
  try {
    const url = new URL(raw);
    return url.origin + url.pathname;
  } catch {
    return raw;
  }
}

/**
 * Whether `url` resolves to an `http:`/`https:` location (rejects `javascript:`,
 * `data:`, `vbscript:`, `mailto:`, etc.). Relative URLs resolve against `base`.
 */
export function isSafeNavigationUrl(url: string, base: string | undefined = defaultBase()): boolean {
  if (!url || typeof url !== 'string') return false;
  try {
    const resolved =
      url.startsWith('http://') || url.startsWith('https://')
        ? new URL(url)
        : new URL(url, base);
    return SAFE_PROTOCOLS.includes(resolved.protocol);
  } catch {
    return false;
  }
}

/**
 * Returns the original `url` if it is safe to put in an `href`, else `undefined`
 * (so callers can render a non-link fallback). Does not rewrite the value — only
 * gates it — so safe relative paths pass through unchanged.
 */
export function safeHref(url: string | undefined | null, base: string | undefined = defaultBase()): string | undefined {
  if (!url) return undefined;
  return isSafeNavigationUrl(url, base) ? url : undefined;
}
