/**
 * Typeahead HTTP call. Kept separate from {@link ApiClient} on purpose:
 *
 *  - The spec requires status-code-discriminated outcomes — a 503 disables
 *    the typeahead surface for the whole session, while other non-2xx codes
 *    only collapse the dropdown for that keystroke. ApiClient throws on
 *    non-2xx and discards the status, so callers can't tell those apart.
 *  - Cancellation is driven by the caller's AbortController so each new
 *    keystroke supersedes the prior in-flight fetch.
 *
 * Contract: verdict-SOI-708-fast-search-path/docs/typeahead-frontend-spec.md
 */

import { API_ENDPOINTS } from './constants.js';
import type {
  TypeaheadRequest,
  TypeaheadResponse,
  TypeaheadResult,
} from './typeahead-types.js';

export const TYPEAHEAD_ENDPOINT = API_ENDPOINTS.TYPEAHEAD_SEARCH;

export interface FetchTypeaheadOptions {
  /** Backend base URL (no trailing slash required). */
  apiBaseUrl: string;
  request: TypeaheadRequest;
  /**
   * Current page URL, sent as the `X-Omniguide-Origin` header so the backend
   * knows which page the search was fired from. Omitted when unavailable.
   */
  origin?: string;
  /** Caller's abort signal — supersede on a new keystroke. */
  signal?: AbortSignal;
  /** Override fetch (tests). Defaults to globalThis.fetch. */
  fetchImpl?: typeof fetch;
}

/**
 * Fire one typeahead request. Never throws — every failure mode maps onto a
 * {@link TypeaheadResult} variant so the caller renders the right state
 * without try/catch at every call site.
 */
export async function fetchTypeaheadSearch(
  opts: FetchTypeaheadOptions,
): Promise<TypeaheadResult> {
  const { apiBaseUrl, request, origin, signal, fetchImpl = fetch } = opts;
  const url = `${apiBaseUrl.replace(/\/$/, '')}${TYPEAHEAD_ENDPOINT}`;

  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  if (origin) {
    headers['X-Omniguide-Origin'] = origin;
  }

  let response: Response;
  try {
    response = await fetchImpl(url, {
      method: 'POST',
      headers,
      body: JSON.stringify(request),
      signal,
    });
  } catch (err) {
    if (err instanceof Error && err.name === 'AbortError') {
      return { kind: 'aborted' };
    }
    return { kind: 'error' };
  }

  // 503 = Typesense disabled/unhealthy — hide the surface for the session.
  if (response.status === 503) {
    return { kind: 'disabled' };
  }
  // Any other non-2xx — collapse the dropdown for this keystroke only.
  if (!response.ok) {
    return { kind: 'error', status: response.status };
  }

  try {
    const data = (await response.json()) as TypeaheadResponse;
    return { kind: 'ok', data };
  } catch {
    return { kind: 'error', status: response.status };
  }
}
